SELECT p.policy_id,p.customer_id,p.broker_id,p.policy_type,p.premium_amount,p.sum_insured,p.risk_band,p.policy_status,COALESCE(SUM(c.claim_amount),0) claim_amount,COALESCE(SUM(c.approved_amount),0) approved_amount FROM stg_policies p LEFT JOIN stg_claims c ON p.policy_id=c.policy_id GROUP BY p.policy_id,p.customer_id,p.broker_id,p.policy_type,p.premium_amount,p.sum_insured,p.risk_band,p.policy_status;
